import{e as t,ab as a,a1 as o,m as i,r as n,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [February]","description":"February 2026 updates","frontmatter":{"title":"Monthly Updates [February]","description":"February 2026 updates","date":"2026-02-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/feb-2026.md","filePath":"posts/feb-2026.md"}'),l={name:"posts/feb-2026.md"};function d(h,e,p,f,g,m){const r=a("Post");return o(),i("div",null,[n(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Our site&#39;s default search is now <strong><a href="https://i.ibb.co/rKNb8CGh/34t34g34.png" target="_blank" rel="noreferrer">Exact Match</a> / <a href="https://i.imgur.com/6XUs4fs.png" target="_blank" rel="noreferrer">2</a></strong>, which is a lot more accurate. You can toggle between both exact and fuzzy. TY to Zenith for doing this.</p></li><li><p>Added <strong><a href="https://i.ibb.co/mCZJzj1N/image.png" target="_blank" rel="noreferrer">Note Tooltips</a> / <a href="https://i.imgur.com/acbozgK.png" target="_blank" rel="noreferrer">2</a></strong> that can be viewed simply by hovering over them. TY to Bread for doing this.</p></li><li><p>You can now navigate through <a href="https://i.ibb.co/5XsSN8bm/image.png" target="_blank" rel="noreferrer">Multiple Result Pages</a> in a single search, page titles are now included in searches, and there is a blur effect behind the window. TY to Bread.</p></li><li><p>Added an <a href="https://i.ibb.co/zVhQJDGt/234234234.png" target="_blank" rel="noreferrer">Index Toggle</a> / <a href="https://i.imgur.com/oYXk3vw.png" target="_blank" rel="noreferrer">2</a> to view only the indexes on a page, similar to the star toggle. TY to Zenith.</p></li><li><p>Fixed multiple mobile issues, including search not updating when typing; the navigation bar will now show immediately when scrolling up, instead of having to go all the way up. TY to Bread.</p></li><li><p>Added <a href="https://i.ibb.co/CpTJ1yL6/234234.png" target="_blank" rel="noreferrer">Monochrome</a> / <a href="https://i.imgur.com/FN54ocn.png" target="_blank" rel="noreferrer">2</a> as an option to the color picker. TY to Zenith.</p></li><li><p>Added a section for <a href="https://fmhy.net/gaming-tools#xbox-homebrew" target="_blank" rel="noreferrer">Xbox Homebrew</a> in Gaming Tools.</p></li><li><p>Added a section for <a href="https://fmhy.net/gaming-tools#undertale-deltarune" target="_blank" rel="noreferrer">Undertale / Deltarune</a> in Gaming Tools. TY to Nattakit, Eitan, Chara, and Clara for making this.</p></li><li><p>Added a section for <a href="https://fmhy.net/gaming-tools#rimworld-tools" target="_blank" rel="noreferrer">RimWorld Tools</a> in Gaming Tools. TY to Litekin for making this.</p></li><li><p>Added a section for <a href="https://fmhy.net/educational#aerospace-engineering" target="_blank" rel="noreferrer">Aerospace Engineering</a> under Educational. TY to Yeet + Manu for making this.</p></li><li><p>Added a section for <a href="https://fmhy.net/gaming#indie-browser-games" target="_blank" rel="noreferrer">Indie Browser Games</a> + Starred Nitrome.</p></li><li><p>Added a section for <a href="https://fmhy.net/gaming#unblocked-games" target="_blank" rel="noreferrer">Unblocked Browser Games</a> + Starred Selenite.</p></li><li><p>Added a section for <a href="https://fmhy.net/misc#hrt-trans-health" target="_blank" rel="noreferrer">HRT / Trans Health</a> under the Health section. TY to April + Pluey for making this.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/gaming-tools#game-launchers" target="_blank" rel="noreferrer">Hydra</a> in Game Launchers. Has plugin-based downloads, torrents, RD + TorBox, good customization, achievements, friends list, playtime monitor, cloud saves, etc. ⁠</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-audio" target="_blank" rel="noreferrer">SpotiFLAC-Mobile</a> in Android Audio. Open-source download app with support for multiple sites.</p></li><li><p>Starred both <a href="https://fmhy.net/gaming-tools#launchers" target="_blank" rel="noreferrer">ElyPrismLauncher + Freesm Launcher</a> in MC Launchers. Both are feature-rich forks of Prism that stood out more than other forks we tried.</p></li><li><p>Starred <a href="https://fmhy.net/ai#official-model-sites" target="_blank" rel="noreferrer">Gemini</a> in AI Chatbots. Gemini 3 Flash works well now and is ranked highly on LMArena.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-youtube-apps" target="_blank" rel="noreferrer">Morphe</a> in Android YouTube + Android YouTube Music. Ad-free YouTube patcher / ReVanced alternative.</p></li><li><p>Starred <a href="https://fmhy.net/video#download-sites" target="_blank" rel="noreferrer">XDMovies + The One Piece</a> in Video Downloading. Both have big libraries + fast hosts.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-video-players" target="_blank" rel="noreferrer">mpvEx</a> in Android Video Players. Feature-rich mpv fork, improved UI, well-maintained.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#download-games" target="_blank" rel="noreferrer">Virgil Game Search</a> in Game Download. Custom multi-site game download search engine; uses only trusted sources.</p></li><li><p>Starred <a href="https://fmhy.net/downloading#freeware-sites" target="_blank" rel="noreferrer">Dan Store</a> in Freeware Sites. Web-based Microsoft Store explorer; bypasses the need for the Microsoft Store app.</p></li><li><p>Starred <a href="https://fmhy.net/reading#ebook-readers" target="_blank" rel="noreferrer">KoReader</a> in Ebook Readers. Open-source, highly customizable, plugin support; very good for e-readers.</p></li><li><p>Starred <a href="https://fmhy.net/video#recommendation-tools" target="_blank" rel="noreferrer">Nothing To Watch</a> in Movie Recommendation Tools. Interactive discovery visualization; a fun/unique way to find something to watch.</p></li><li><p>Starred <a href="https://fmhy.net/educational#geography-sociology" target="_blank" rel="noreferrer">Ekvis</a> in Geography. Well-maintained and useful geography learning site; covers 220+ countries, flags, territories, etc.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#browser-games" target="_blank" rel="noreferrer">Slope Plus</a> in Browser Games. Updated version of Slope; has extra features, game modes, and an active custom map community.</p></li><li><p>Starred <a href="https://fmhy.net/ai#video-generation" target="_blank" rel="noreferrer">GeminiGen AI</a> in Image + Video Gen. Gives unlimited Nano Banana Pro images, and unlimited Sora 2, Veo 3.1, and Grok videos.</p></li><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">Perchance</a> Image Gen. Unlimited, no sign-up required, and has improved a lot quality-wise.</p></li><li><p>Starred <a href="https://fmhy.net/audio#lofi-radio" target="_blank" rel="noreferrer">Flow-Fi</a> in Lo-Fi Radio. Has lots of options for stations and video backgrounds; higher-quality than most lo-fi sites we&#39;re sent.</p></li><li><p>Starred <a href="https://fmhy.net/misc#navigation-transport" target="_blank" rel="noreferrer">StreetComplete</a> in the Navigation section. Helps fill in missing OpenStreetMap data by completing quests.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#multi-game-sites" target="_blank" rel="noreferrer">Flash Arch, Kongregate, &amp; Crazy Games</a> in Browser Games. After going through this section, these three seemed to stand out the most, but if we missed any other good ones, feel free to let us know. We did also consider AddictingGames + Poki, but were too unsure on both.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed BATO.to as <a href="https://i.ibb.co/67mzHCsW/234234234.png" target="_blank" rel="noreferrer">their staff has been threatened</a> / <a href="https://i.imgur.com/84cioY3.png" target="_blank" rel="noreferrer">2</a>, and they&#39;ve been forced to shut down the site.</p></li><li><p>Removed EeveeSpotifyReborn as it&#39;s been archived.</p></li><li><p>Removed MangaPark as their site is redirecting to ads now.</p></li></ul>',9))])}const b=t(l,[["render",d]]);export{u as __pageData,b as default};
